mapper.sql:
FROM flow_ledger fl
LEFT JOIN node n ON fl.node_id = n.id
LEFT JOIN forward f ON fl.forward_id = f.id
LEFT JOIN `user` u ON fl.user_id = u.id
LEFT JOIN tunnel t ON fl.tunnel_id = t.id


        AND fl.user_id = #{query.userId}


        AND fl.tunnel_id = #{query.tunnelId}


        AND fl.forward_id = #{query.forwardId}


        AND fl.node_id = #{query.nodeId}


        AND fl.user_tunnel_id = #{query.userTunnelId}


        AND fl.billing_mode = #{query.billingMode}


        AND fl.service_name LIKE CONCAT('%', #{query.serviceName}, '%')


        AND (
            fl.service_name LIKE CONCAT('%', #{query.keyword}, '%')
            OR u.user LIKE CONCAT('%', #{query.keyword}, '%')
            OR t.name LIKE CONCAT('%', #{query.keyword}, '%')
            OR f.name LIKE CONCAT('%', #{query.keyword}, '%')
            OR n.name LIKE CONCAT('%', #{query.keyword}, '%')
        )


        AND fl.created_time >= #{query.startTime}


        AND fl.created_time <= #{query.endTime}
